function mostrarThis() {
  console.log(this);
}

mostrarThis(); // binding por defeito: undefined (modo estrito)

const utilizador = {
  nome: "Marta",
  cumprimentar() {
    console.log(`Olá, sou ${this.nome}`); // binding implícito
  },
};

utilizador.cumprimentar(); // "Olá, sou Marta" — this é `utilizador`

function apresentar(saudacao, pontuacao) {
  console.log(`${saudacao}, ${this.nome}${pontuacao}`);
}

const maria = { nome: "Maria" };
const joao = { nome: "João" };

apresentar.call(maria, "Bom dia", "!");   // "Bom dia, Maria!" — argumentos passados um a um
apresentar.apply(joao, ["Olá", "..."]);   // "Olá, João..." — argumentos passados num array

const numeros = { 0: 10, 1: 25, 2: 7, length: 3 };
const maior = Math.max.apply(null, numeros); // "empresta" Math.max para um array-like
console.log(maior); // 25

const contador = {
  valor: 0,
  incrementar() {
    this.valor++;
    console.log(this.valor);
  },
};

const incrementarFixo = contador.incrementar.bind(contador);
setTimeout(incrementarFixo, 100); // this continua a ser `contador`

function multiplicar(a, b) {
  return a * b;
}

const duplicar = multiplicar.bind(null, 2); // fixa o primeiro argumento
console.log(duplicar(21)); // 42

function Produto(nome, preco) {
  this.nome = nome;
  this.preco = preco;
}

const cadeira = new Produto("Cadeira", 89.9);
console.log(cadeira.nome, cadeira.preco); // "Cadeira" 89.9

function ProdutoComDesconto(nome, preco) {
  this.nome = nome;
  this.preco = preco * 0.9;
}

const mesa = new ProdutoComDesconto("Mesa", 100);
console.log(mesa.preco); // 90 — `this` dentro do construtor era a nova instância

function mostrar() {
  console.log(this.nome);
}

const objeto = { nome: "Objeto", mostrar };
const mostrarComOutroThis = mostrar.bind({ nome: "Bind" });

objeto.mostrar();          // "Objeto" — binding implícito
mostrarComOutroThis();    // "Bind"   — binding explícito vence sobre o implícito
new mostrarComOutroThis(); // undefined — `new` cria um novo objeto (sem a propriedade nome) e ignora o this fixado por bind: new vence sobre o binding explícito

const relogio = {
  horas: 0,
  iniciar() {
    // arrow function: `this` aqui é herdado de `iniciar`, ou seja, é `relogio`
    setInterval(() => {
      this.horas++;
      console.log(this.horas);
    }, 1000);
  },
  iniciarComProblema() {
    // function tradicional: não herda `this` — perde a ligação a `relogio`
    setInterval(function () {
      console.log(this); // undefined ou objeto global, não `relogio`
    }, 1000);
  },
};

const botao = {
  rotulo: "Guardar",
  aoClicar() {
    console.log(`Clicado: ${this.rotulo}`);
  },
};

function simularClique(callback) {
  callback(); // chamada isolada, sem objeto antes do ponto
}

simularClique(botao.aoClicar);
// -> TypeError: Cannot read properties of undefined (reading 'rotulo')

simularClique(botao.aoClicar.bind(botao));
// -> "Clicado: Guardar" — this fixado explicitamente com bind

simularClique(() => botao.aoClicar());
// -> "Clicado: Guardar" — arrow function preserva o binding implícito no momento da chamada

exercises.statement:
Dado o código abaixo, sem o executar, indique o que é impresso na consola em cada uma das três chamadas e diga qual das três regras de binding (por defeito, implícito ou explícito) está a ser aplicada em cada caso.

function mostrarNome() {
  console.log(this?.nome);
}

const pessoa = { nome: "Rita", mostrarNome };

mostrarNome();
pessoa.mostrarNome();
mostrarNome.call({ nome: "Tiago" });

exercises.solution_code:
function mostrarNome() {
  console.log(this?.nome);
}

const pessoa = { nome: "Rita", mostrarNome };

mostrarNome();                        // undefined — binding por defeito (this é undefined em modo estrito)
pessoa.mostrarNome();                 // "Rita"    — binding implícito (this é `pessoa`)
mostrarNome.call({ nome: "Tiago" });  // "Tiago"   — binding explícito (this fixado por `call`)

const contador = {
  valor: 0,
  incrementar(passo) {
    this.valor += passo;
    return this.valor;
  },
};

const incrementarEmDois = contador.incrementar.bind(contador, 2);

console.log(incrementarEmDois()); // 2
console.log(incrementarEmDois()); // 4

exercises.statement:
O código abaixo tem um erro: quando obj.processar é passado como callback para a função executar, this deixa de apontar para obj e o programa lança um TypeError ao tentar ler this.total dentro do método. Sem alterar a função executar, escreva a chamada a executar de duas formas diferentes que corrijam o problema — uma usando bind, outra usando uma arrow function que envolve a chamada ao método — e mostre que ambas imprimem 10.

const obj = {
  total: 10,
  processar() {
    console.log(this.total);
  },
};

function executar(callback) {
  callback();
}

executar(obj.processar); // TypeError: Cannot read properties of undefined (reading 'total')

exercises.solution_code:
const obj = {
  total: 10,
  processar() {
    console.log(this.total);
  },
};

function executar(callback) {
  callback();
}

// versão 1: bind fixa `this` explicitamente antes de passar a função
executar(obj.processar.bind(obj)); // 10

// versão 2: a arrow function preserva o binding implícito no momento da chamada
executar(() => obj.processar()); // 10

function meuBind(fn, thisArg, ...argsFixos) {
  return function (...argsChamada) {
    return fn.apply(thisArg, [...argsFixos, ...argsChamada]);
  };
}

function somar(a, b, c) {
  return a + b + c;
}

const somarComPrimeiroFixo = meuBind(somar, null, 10);
console.log(somarComPrimeiroFixo(5, 2)); // 17

const objeto = { fator: 3 };
function multiplicarPorFator(valor) {
  return valor * this.fator;
}

const multiplicarFixo = meuBind(multiplicarPorFator, objeto);
console.log(multiplicarFixo(7)); // 21
